  "bcom_law-exam-day-1": "const passRes = evaluateDay1AuditMetric(95, 90, 71);\nconst failRes = evaluateDay1AuditMetric(40, 50, 71);\nif (!passRes || passRes.weightedScore !== 93 || !passRes.isCompliant || passRes.status !== 'CORPORATE_LEGAL_DAY_1_COMPLIANT') throw new Error('Compliant evaluation failed on Day 1');\nif (!failRes || failRes.weightedScore !== 44 || failRes.isCompliant || failRes.status !== 'CORPORATE_LEGAL_DAY_1_VARIANCE_ALERT') throw new Error('Variance alert evaluation failed on Day 1');",
