  "bcom_tax-assign-day-7": "const v1 = calculateDay7VarianceIndex(105, 100);\nconst v2 = calculateDay7VarianceIndex(130, 100);\nif (!v1 || v1.varianceAmount !== 5 || v1.variancePct !== 5 || !v1.withinTolerance) throw new Error('Tolerance check failed for 5% variance');\nif (!v2 || v2.varianceAmount !== 30 || v2.variancePct !== 30 || v2.withinTolerance) throw new Error('Out-of-tolerance check failed for 30% variance');",
  "bcom_tax-assign-day-8": "const v1 = calculateDay8VarianceIndex(105, 100);\nconst v2 = calculateDay8VarianceIndex(130, 100);\nif (!v1 || v1.varianceAmount !== 5 || v1.variancePct !== 5 || !v1.withinTolerance) throw new Error('Tolerance check failed for 5% variance');\nif (!v2 || v2.varianceAmount !== 30 || v2.variancePct !== 30 || v2.withinTolerance) throw new Error('Out-of-tolerance check failed for 30% variance');",
  "bcom_tax-assign-day-9": "const v1 = calculateDay9VarianceIndex(105, 100);\nconst v2 = calculateDay9VarianceIndex(130, 100);\nif (!v1 || v1.varianceAmount !== 5 || v1.variancePct !== 5 || !v1.withinTolerance) throw new Error('Tolerance check failed for 5% variance');\nif (!v2 || v2.varianceAmount !== 30 || v2.variancePct !== 30 || v2.withinTolerance) throw new Error('Out-of-tolerance check failed for 30% variance');",
  "bcom_tax-exam-day-1": "const passRes = evaluateDay1AuditMetric(95, 90, 71);\nconst failRes = evaluateDay1AuditMetric(40, 50, 71);\nif (!passRes || passRes.weightedScore !== 93 || !passRes.isCompliant || passRes.status !== 'CORPORATE_TAX_DAY_1_COMPLIANT') throw new Error('Compliant evaluation failed on Day 1');\nif (!failRes || failRes.weightedScore !== 44 || failRes.isCompliant || failRes.status !== 'CORPORATE_TAX_DAY_1_VARIANCE_ALERT') throw new Error('Variance alert evaluation failed on Day 1');",
  "bcom_tax-exam-day-10": "const passRes = evaluateDay10AuditMetric(95, 90, 80);\nconst failRes = evaluateDay10AuditMetric(40, 50, 80);\nif (!passRes || passRes.weightedScore !== 93 || !passRes.isCompliant || passRes.status !== 'CORPORATE_TAX_DAY_10_COMPLIANT') throw new Error('Compliant evaluation failed on Day 10');\nif (!failRes || failRes.weightedScore !== 44 || failRes.isCompliant || failRes.status !== 'CORPORATE_TAX_DAY_10_VARIANCE_ALERT') throw new Error('Variance alert evaluation failed on Day 10');",
