  "fullstack-js-assign-day-51": "const q1 = formatRoleQuery('button', 'Save');\nif (q1 !== \"screen.getByRole('button', { name: 'Save' })\") throw new Error('Query format failed for button');\nconst q2 = formatRoleQuery('textbox', 'Username');\nif (q2 !== \"screen.getByRole('textbox', { name: 'Username' })\") throw new Error('Query format failed for textbox');\nconst q3 = formatRoleQuery('checkbox', 'Agree');\nif (q3 !== \"screen.getByRole('checkbox', { name: 'Agree' })\") throw new Error('Query format failed for checkbox');",
