  "fullstack-js-assign-day-8": "// Test 1: Descending with leading hyphen\nconst desc = parseSortParam('-created_at');\nif (desc.field !== 'created_at' || desc.order !== 'DESC') throw new Error('Descending sort parsing failed');\n\n// Test 2: Ascending standard field\nconst asc = parseSortParam('name');\nif (asc.field !== 'name' || asc.order !== 'ASC') throw new Error('Ascending sort parsing failed');\n\n// Test 3: Ascending with explicit leading plus\nconst plus = parseSortParam('+price');\nif (plus.field !== 'price' || plus.order !== 'ASC') throw new Error('Explicit plus sort parsing failed');\n\n// Test 4: Default fallback\nconst def = parseSortParam();\nif (def.field !== 'id' || def.order !== 'ASC') throw new Error('Default sort fallback failed');",
