  "fullstack-js-assign-day-85": "const headers = getSseHeaders();\nif (headers['Content-Type'] !== 'text/event-stream') throw new Error('Content-Type must be text/event-stream');\nif (headers['Cache-Control'] !== 'no-cache') throw new Error('Cache-Control must be no-cache');\nif (headers['Connection'] !== 'keep-alive') throw new Error('Connection must be keep-alive');\nif (headers['X-Accel-Buffering'] !== 'no') throw new Error('X-Accel-Buffering must be no');",
