  "fullstack-js-assign-day-9": "const nowSec = Date.now() / 1000;\nif (isJwtExpired(nowSec - 100) !== true) throw new Error('Past timestamp must be expired');\nif (isJwtExpired(nowSec + 1000) !== false) throw new Error('Future timestamp must not be expired');\nif (isJwtExpired(nowSec - 10, 30) !== false) throw new Error('Token within clock skew tolerance window must remain valid');",
