  "fullstack-js-exam-day-8": "const list = Array.from({ length: 25 }, (_, i) => ({ id: i + 1 }));\n\n// Test 1: Page 1 with limit 10\nconst p1 = paginateCollection(list, { page: '1', limit: '10' });\nif (!p1.pagination || p1.data.length !== 10) throw new Error('Page 1 data slice length mismatch');\nif (p1.pagination.page !== 1 || p1.pagination.limit !== 10) throw new Error('Page 1 page/limit mismatch');\nif (p1.pagination.total !== 25 || p1.pagination.totalPages !== 3) throw new Error('Total or totalPages mismatch');\nif (p1.pagination.hasNext !== true || p1.pagination.hasPrev !== false) throw new Error('Page 1 navigation flags mismatch');\n\n// Test 2: Page 3 with limit 10 (Tail page)\nconst p3 = paginateCollection(list, { page: '3', limit: '10' });\nif (p3.data.length !== 5) throw new Error('Tail page data length must be 5');\nif (p3.pagination.hasNext !== false || p3.pagination.hasPrev !== true) throw new Error('Tail page navigation flags mismatch');\nif (p3.data[0].id !== 21 || p3.data[4].id !== 25) throw new Error('Tail page item IDs mismatch');\n\n// Test 3: Default parameters (page 1, limit 10)\nconst def = paginateCollection(list);\nif (def.pagination.page !== 1 || def.pagination.limit !== 10 || def.data.length !== 10) {\n  throw new Error('Default pagination parameters failed');\n}\n\n// Test 4: Empty items array\nconst empty = paginateCollection([], { page: 1, limit: 10 });\nif (empty.data.length !== 0 || empty.pagination.total !== 0 || empty.pagination.totalPages !== 0) {\n  throw new Error('Empty collection pagination failed');\n}\nif (empty.pagination.hasNext !== false || empty.pagination.hasPrev !== false) {\n  throw new Error('Empty collection navigation flags must be false');\n}",
